def count_median_pairs():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:]))

    # Find the position of m in the array
    pos_m = -1
    for i in range(n):
        if a[i] == m:
            pos_m = i
            break

    if pos_m == -1:
        print(0)
        return

    # Calculate prefix sums of balance
    balance = 0
    balance_count = {0: 1}
    result = 0

    for i in range(pos_m, n):
        if a[i] > m:
            balance += 1
        elif a[i] < m:
            balance -= 1

        if balance in balance_count:
            balance_count[balance] += 1
        else:
            balance_count[balance] = 1

    balance = 0

    for i in range(pos_m, -1, -1):
        if a[i] > m:
            balance += 1
        elif a[i] < m:
            balance -= 1

        if balance in balance_count:
            result += balance_count[balance]
        if balance - 1 in balance_count:
            result += balance_count[balance - 1]

    print(result)

