    input = sys.stdin.read
    a, b, c, d = map(int, input().strip().split())

    operators = ['+', '-', '*', '/']
    results = []

    for op1 in operators:
        for op2 in operators:
            try:
                if op1 == '+':
                    left = a + b
                elif op1 == '-':
                    left = a - b
                elif op1 == '*':
                    left = a * b
                elif op1 == '/':
                    if b == 0:
                        continue
                    left = a // b

                if op2 == '+':
                    right = c + d
                elif op2 == '-':
                    right = c - d
                elif op2 == '*':
                    right = c * d
                elif op2 == '/':
                    if d == 0:
                        continue
                    right = c // d

                if left == right:
                    results.append(f"{a} {op1} {b} = {c} {op2} {d}")
            except ZeroDivisionError:
                continue

    if results:
        results.sort()
        for result in results:
            print(result)
    else:
        print("problems ahead")
