def find_minimum_x():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        divisors = list(map(int, data[index:index + n]))
        index += n

        divisors.sort()
        x = divisors[0] * divisors[-1]

        # Check if x is valid
        valid = True
        for i in range(n):
            if x % divisors[i] != 0:
                valid = False
                break

        if valid:
            # Check if all divisors of x (except 1 and x) are in the list
            all_divisors = set()
            for i in range(2, int(x**0.5) + 1):
                if x % i == 0:
                    all_divisors.add(i)
                    if i != x // i:
                        all_divisors.add(x // i)

            if all_divisors == set(divisors):
                results.append(x)
            else:
                results.append(-1)
        else:
            results.append(-1)

    for result in results:
        print(result)

