def play_2048():
    import sys
    input = sys.stdin.read
    data = input().split()

    grid = [list(map(int, data[i*4:(i+1)*4])) for i in range(4)]
    move = int(data[16])

    def merge_line(line):
        new_line = [i for i in line if i != 0]
        merged_line = []
        skip = False
        for i in range(len(new_line)):
            if skip:
                skip = False
                continue
            if i + 1 < len(new_line) and new_line[i] == new_line[i + 1]:
                merged_line.append(new_line[i] * 2)
                skip = True
            else:
                merged_line.append(new_line[i])
        return merged_line + [0] * (4 - len(merged_line))

    def move_left(grid):
        return [merge_line(row) for row in grid]

    def move_right(grid):
        return [merge_line(row[::-1])[::-1] for row in grid]

    def move_up(grid):
        transposed = list(zip(*grid))
        moved = [merge_line(list(row)) for row in transposed]
        return [list(row) for row in zip(*moved)]

    def move_down(grid):
        transposed = list(zip(*grid))
        moved = [merge_line(list(row)[::-1])[::-1] for row in transposed]
        return [list(row) for row in zip(*moved)]

    if move == 0:
        result = move_left(grid)
    elif move == 1:
        result = move_up(grid)
    elif move == 2:
        result = move_right(grid)
    elif move == 3:
        result = move_down(grid)

    for row in result:
        print(' '.join(map(str, row)))

