def find_smallest_integer():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    constraints = {}
    for i in range(M):
        s_i = int(data[2 + 2 * i])
        c_i = int(data[3 + 2 * i])
        if s_i in constraints and constraints[s_i] != c_i:
            print(-1)
            return
        constraints[s_i] = c_i

    result = [-1] * N

    for pos, digit in constraints.items():
        result[pos - 1] = digit

    if N > 1 and result[0] == -1:
        result[0] = 1

    for i in range(N):
        if result[i] == -1:
            result[i] = 0

    if N > 1 and result[0] == 0:
        print(-1)
        return

    print(''.join(map(str, result)))

