    input = sys.stdin.read
    data = input().splitlines()

    N = int(data[0])
    words = data[1:]

    number_words = {
        1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
        6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
        11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
        15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen",
        19: "nineteen", 20: "twenty", 30: "thirty", 40: "forty",
        50: "fifty", 60: "sixty", 70: "seventy", 80: "eighty",
        90: "ninety"
    }

    def number_to_words(n):
        if n <= 20:
            return number_words[n]
        elif n < 100:
            tens, ones = divmod(n, 10)
            return number_words[tens * 10] + (number_words[ones] if ones else "")
        else:
            hundreds, remainder = divmod(n, 100)
            return number_words[hundreds] + "hundred" + (number_to_words(remainder) if remainder else "")

    def calculate_sentence_length(words, number_word):
        return sum(len(word) for word in words) + len(number_word) - 1

    for i in range(1, 1000):
        number_word = number_to_words(i)
        if calculate_sentence_length(words, number_word) == i:
            words[words.index('$')] = number_word
            print(" ".join(words))
            break

