def can_complete_wall():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    if n == 1:
        print("YES")
        return

    # Check if the wall can be completed
    for i in range(n - 1):
        if a[i] > a[i + 1]:
            print("NO")
            return

    if (a[-1] - a[0]) % 2 == 0:
        print("YES")
    else:
        print("NO")
