def max_distance_to_maintain_convexity():
    import sys
    input = sys.stdin.read
    from math import sqrt

    data = input().split()
    n = int(data[0])
    points = [(int(data[i * 2 + 1]), int(data[i * 2 + 2])) for i in range(n)]

    def distance(p1, p2):
        return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def is_convex():
        for i in range(n):
            if cross(points[i], points[(i + 1) % n], points[(i + 2) % n]) <= 0:
                return False
        return True

    def can_move(d):
        for i in range(n):
            p1 = points[i]
            p2 = points[(i + 1) % n]
            p3 = points[(i + 2) % n]
            if cross(p1, p2, p3) <= 0:
                return False
            if distance(p1, p2) < 2 * d or distance(p2, p3) < 2 * d:
                return False
        return True

    low, high = 0, min(distance(points[i], points[(i + 1) % n]) / 2 for i in range(n))
    while high - low > 1e-7:
        mid = (low + high) / 2
        if can_move(mid):
            low = mid
        else:
            high = mid

    print(f"{low:.10f}")

