def count_non_shortest_path_edges():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    edges = []
    index = 2
    for _ in range(M):
        a = int(data[index]) - 1
        b = int(data[index + 1]) - 1
        c = int(data[index + 2])
        edges.append((a, b, c))
        index += 3

    # Initialize distance matrix with infinity
    inf = float('inf')
    dist = [[inf] * N for _ in range(N)]

    # Distance from a vertex to itself is 0
    for i in range(N):
        dist[i][i] = 0

    # Set initial distances based on edges
    for a, b, c in edges:
        dist[a][b] = c
        dist[b][a] = c

    # Floyd-Warshall algorithm to find all pairs shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Count edges not in any shortest path
    non_shortest_path_edges = 0
    for a, b, c in edges:
        in_shortest_path = False
        for i in range(N):
            for j in range(N):
                if dist[i][j] == dist[i][a] + c + dist[b][j]:
                    in_shortest_path = True
                    break
            if in_shortest_path:
                break
        if not in_shortest_path:
            non_shortest_path_edges += 1

    print(non_shortest_path_edges)

