def count_valid_strings():
    import sys
    input = sys.stdin.read
    MOD = 10**9 + 7

    N = int(input().strip())

    # dp[i][a][b][c] = number of valid strings of length i where the last three characters are a, b, c
    dp = [[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(N + 1)]

    # Mapping A, C, G, T to 0, 1, 2, 3
    A, C, G, T = 0, 1, 2, 3

    # Initialize base case
    dp[0][3][3][3] = 1  # Start with an empty string

    for i in range(N):
        for a in range(4):
            for b in range(4):
                for c in range(4):
                    if dp[i][a][b][c] == 0:
                        continue
                    for d in range(4):
                        # Check if adding character d violates the conditions
                        if (b == A and c == G and d == C) or (b == G and c == A and d == C) or (b == A and c == C and d == G):
                            continue
                        if (a == A and c == G and d == C) or (a == A and b == G and d == C):
                            continue
                        dp[i + 1][b][c][d] = (dp[i + 1][b][c][d] + dp[i][a][b][c]) % MOD

    # Sum up all valid strings of length N
    result = 0
    for a in range(4):
        for b in range(4):
            for c in range(4):
                result = (result + dp[N][a][b][c]) % MOD

    print(result)

