def count_sequences():
    import sys
    input = sys.stdin.read
    MOD = 1000000007

    a11, a12, a21, a22, N = map(int, input().strip().split())

    # Total number of players
    total_players = a11 + a12 + a21 + a22

    # If there are less than 3 players, no valid sequence can be formed
    if total_players < 3:
        print(0)
        return

    # Calculate the number of ways to choose 3 distinct players
    def comb(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        if k == 1:
            return n
        if k == 2:
            return n * (n - 1) // 2
        if k == 3:
            return n * (n - 1) * (n - 2) // 6
        return 0

    # Calculate the number of valid sequences
    if N == 1:
        # For N = 1, any pair of players can form a valid move
        result = total_players * (total_players - 1) % MOD
    elif N == 2:
        # For N = 2, any two distinct pairs can form a valid sequence
        result = total_players * (total_players - 1) * (total_players - 2) % MOD
    else:
        # For N >= 3, we need to consider the resting rule
        if N % 3 == 0:
            # If N is a multiple of 3, the sequence must end with a rest
            result = 0
        else:
            # Otherwise, calculate the number of sequences
            result = comb(total_players, 3) * pow(2, N - 3, MOD) % MOD

    print(result)

