        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def dfs(node, color):
        colors[node] = color
        for neighbor in adj[node]:
            if colors[neighbor] == -1:
                if not dfs(neighbor, 1 - color):
                    return False
            elif colors[neighbor] == color:
                return False
        return True

    for i in range(n):
        if colors[i] == -1:
            if not dfs(i, 0):
                print("No")
                return

    a_group = [i for i in range(n) if colors[i] == 0]
    b_group = [i for i in range(n) if colors[i] == 1]

    if len(a_group) == 0 or len(b_group) == 0:
