    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    p = int(data[2])

    board = []
    index = 3
    for _ in range(n):
        board.append([int(data[index + j]) for j in range(m)])
        index += m

    def is_winning(board):
        return all(all(cell == p for cell in row) for row in board)

    def apply_move(board, r, c):
        for i in range(n):
            board[i][c] = (board[i][c] % p) + 1
        for j in range(m):
            if j != c:
                board[r][j] = (board[r][j] % p) + 1

    def find_solution():
        moves = []
        for r in range(n):
            for c in range(m):
                while board[r][c] != p:
                    apply_move(board, r, c)
                    moves.append(r * m + c + 1)
                    if len(moves) > p * m * n:
                        return -1
        if is_winning(board):
            return moves
        return -1

    result = find_solution()
    if result == -1:
        print(-1)
    else:
        print(len(result))
        print(' '.join(map(str, result)))

