    k = int(data[1])
    m = int(data[2])
    a = int(data[3])
    votes = list(map(int, data[4:4+a]))

    vote_count = [0] * n
    last_vote_time = [-1] * n

    for i, v in enumerate(votes):
        vote_count[v-1] += 1
        last_vote_time[v-1] = i

    results = [3] * n

    for i in range(n):
        if vote_count[i] > 0:
            # Check if candidate i is guaranteed to win
            potential_winners = 0
            for j in range(n):
                if j != i:
                    if vote_count[j] > vote_count[i]:
                        potential_winners += 1
                    elif vote_count[j] == vote_count[i] and last_vote_time[j] < last_vote_time[i]:
                        potential_winners += 1
            if potential_winners < k:
                results[i] = 1
            else:
                # Check if candidate i has a chance to win
                potential_winners = 0
                for j in range(n):
                    if j != i:
                        if vote_count[j] > vote_count[i] + (m - a):
                            potential_winners += 1
                        elif vote_count[j] == vote_count[i] + (m - a) and last_vote_time[j] < last_vote_time[i]:
                            potential_winners += 1
                if potential_winners < k:
                    results[i] = 2

