def determine_candidates():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    m = int(data[2])
    a = int(data[3])
    votes = list(map(int, data[4:4+a]))

    vote_count = [0] * n
    last_vote_time = [-1] * n

    for i, v in enumerate(votes):
        vote_count[v-1] += 1
        last_vote_time[v-1] = i

    results = [3] * n

    for i in range(n):
        if vote_count[i] > 0:
            max_possible_votes = vote_count[i] + (m - a)
            if max_possible_votes < k:
                results[i] = 3
            else:
                sorted_candidates = sorted(
                    [(vote_count[j], last_vote_time[j], j) for j in range(n)],
                    key=lambda x: (-x[0], x[1])
                )

                position = next((index for index, (_, _, idx) in enumerate(sorted_candidates) if idx == i), None)

                if position is not None and position < k:
                    results[i] = 1
                else:
                    sorted_candidates = sorted(
                        [(vote_count[j] + (m - a if j == i else 0), last_vote_time[j], j) for j in range(n)],
                        key=lambda x: (-x[0], x[1])
                    )

                    position = next((index for index, (_, _, idx) in enumerate(sorted_candidates) if idx == i), None)

                    if position is not None and position < k:
                        results[i] = 2
                    else:
                        results[i] = 3
        else:
            results[i] = 3

    print(' '.join(map(str, results)))

