def min_moves_to_goal():
    import sys
    from collections import deque

    input = sys.stdin.read
    data = input().splitlines()

    C, R = map(int, data[0].split())
    maze = [list(line) for line in data[1:R+1]]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def glide(x, y, dx, dy):
        while True:
            nx, ny = x + dx, y + dy
            if maze[ny][nx] == '#':
                return x, y
            elif maze[ny][nx] == '.':
                return nx, ny
            x, y = nx, ny

    goal = None
    for y in range(R):
        for x in range(C):
            if maze[y][x] == 'M':
                goal = (x, y)
                break
        if goal:
            break

    moves = [[-1] * C for _ in range(R)]
    queue = deque([goal])
    moves[goal[1]][goal[0]] = 0

    while queue:
        x, y = queue.popleft()
        current_moves = moves[y][x]

        for dx, dy in directions:
            nx, ny = glide(x, y, dx, dy)
            if moves[ny][nx] == -1:
                moves[ny][nx] = current_moves + 1
                queue.append((nx, ny))

    for row in moves:
        print(' '.join(map(str, row)))

