def min_moves_to_goal():
    import sys
    input = sys.stdin.read
    from collections import deque

    data = input().split()
    C, R = int(data[0]), int(data[1])
    maze = data[2:]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    goal = None

    for r in range(R):
        for c in range(C):
            if maze[r][c] == 'M':
                goal = (r, c)
                break
        if goal:
            break

    moves = [[-1] * C for _ in range(R)]
    queue = deque([goal])
    moves[goal[0]][goal[1]] = 0

    while queue:
        r, c = queue.popleft()
        current_moves = moves[r][c]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            while 0 <= nr < R and 0 <= nc < C and maze[nr][nc] == '_':
                nr += dr
                nc += dc

            if 0 <= nr < R and 0 <= nc < C and maze[nr][nc] == '.':
                if moves[nr][nc] == -1 or moves[nr][nc] > current_moves + 1:
                    moves[nr][nc] = current_moves + 1
                    queue.append((nr, nc))
            elif 0 <= nr < R and 0 <= nc < C and maze[nr][nc] == '#':
                nr -= dr
                nc -= dc
                if moves[nr][nc] == -1 or moves[nr][nc] > current_moves + 1:
                    moves[nr][nc] = current_moves + 1
                    queue.append((nr, nc))

    for row in moves:
        print(' '.join(map(str, row)))

