def river_crossing():
    import sys
    from collections import deque

    input = sys.stdin.read
    data = input().split()

    P = int(data[0])
    R = int(data[1])
    L = int(data[2])

    edges = []
    index = 3
    for _ in range(L):
        E1 = int(data[index])
        E2 = int(data[index + 1])
        edges.append((E1, E2))
        index += 2

    # Create adjacency list
    graph = {}
    for E1, E2 in edges:
        if E1 not in graph:
            graph[E1] = []
        if E2 not in graph:
            graph[E2] = []
