def divisibility_hack():
    import sys
    input = sys.stdin.read
    b, d = map(int, input().strip().split())

    # Check if there exists a positive integer m such that (b^m - 1) is divisible by d
    # This is equivalent to checking if b is a primitive root modulo d
    # A number b is a primitive root modulo d if the order of b modulo d is d-1
    # The order of b modulo d is the smallest positive integer m such that b^m ≡ 1 (mod d)

    # We need to check if b^m ≡ 1 (mod d) for some m that divides d-1
    # If b^(d-1) ≡ 1 (mod d), then b is a primitive root modulo d if no smaller power of b is congruent to 1 mod d

    def mod_exp(base, exp, mod):
        result = 1
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp //= 2
        return result

    def is_primitive_root(b, d):
        if mod_exp(b, d-1, d) != 1:
            return False
        # Check all divisors of d-1
        phi = d - 1
        m = 1
        while m * m <= phi:
            if phi % m == 0:
                if mod_exp(b, m, d) == 1:
                    return False
                if m != phi // m and mod_exp(b, phi // m, d) == 1:
                    return False
            m += 1
        return True

    if is_primitive_root(b, d):
        print("yes")
    else:
        print("no")
