import sys
import itertools
import math

def calculate_length(points):
    length = 0
    for i in range(len(points)):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % len(points)]
        length += math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
    return length

def is_balanced(inside, outside):
    sum_inside = sum(e for _, _, e in inside)
    sum_outside = sum(e for _, _, e in outside)
    return sum_inside == sum_outside

def find_balancing_line(lamps):
    n = len(lamps)
    for r in range(1, n):
        for inside_indices in itertools.combinations(range(n), r):
            inside = [lamps[i] for i in inside_indices]
            outside = [lamps[i] for i in range(n) if i not in inside_indices]
            if is_balanced(inside, outside):
                inside_points = [(x, y) for x, y, _ in inside]
                outside_points = [(x, y) for x, y, _ in outside]
                all_points = inside_points + outside_points
                hull = convex_hull(all_points)
                return calculate_length(hull)
    return "IMPOSSIBLE"

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
