        result = []
        for i in range(0, N, A):
            result.extend(range(i + 1, i + A + 1))
        print(' '.join(map(str, result)))
        return

    if N % B == 0:
        result = []
        for i in range(0, N, B):
            result.extend(range(i + 1, i + B + 1))
        print(' '.join(map(str, result)))
        return

