        if (N - x * A) % B == 0:
            result = []
            for i in range(x):
                result.extend(range(i * A + 1, (i + 1) * A + 1))
            for i in range((N - x * A) // B):
                result.extend(range(x * A + i * B + 1, x * A + (i + 1) * B + 1))
            print(' '.join(map(str, result)))
