import sys
import math
from collections import defaultdict, deque

def min_path_sum():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = list(map(int, data[1:n+1]))

    max_k = max(k)
    max_factorial = math.factorial(max_k)

    # Precompute factorials
    factorials = [math.factorial(i) for i in range(max_k + 1)]

    # Precompute lowest prime divisor for each number up to max_factorial
    lpd = list(range(max_factorial + 1))
    for i in range(2, int(math.sqrt(max_factorial)) + 1):
        if lpd[i] == i:
            for j in range(i * i, max_factorial + 1, i):
                if lpd[j] == j:
                    lpd[j] = i

    # BFS to calculate distances from each factorial node
    def bfs(start):
        distances = {}
        queue = deque([(start, 0)])
        visited = set()

        while queue:
            node, dist = queue.popleft()
            if node in visited:
                continue
            visited.add(node)
            distances[node] = dist

            if node > 1:
                next_node = node // lpd[node]
                if next_node not in visited:
                    queue.append((next_node, dist + 1))

        return distances

    # Calculate distances from each factorial node
    all_distances = {}
    for ki in k:
        fact = factorials[ki]
        if fact not in all_distances:
            all_distances[fact] = bfs(fact)

    # Find the optimal node P
    min_sum = float('inf')
    for fact in all_distances:
        current_sum = 0
        for ki in k:
            current_sum += all_distances[fact][factorials[ki]]
        min_sum = min(min_sum, current_sum)

    print(min_sum)

