import math
from heapq import heappop, heappush

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def distance(hill1, hill2):
    x1, y1, h1 = hill1
    x2, y2, h2 = hill2
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2 + (h2 - h1) ** 2)

def min_aqueduct_length():
    n, s, t, q = read_ints()
    hills = [tuple(read_ints()) for _ in range(n)]
    springs = read_ints()
    towns = read_ints()

    # Create a graph with edges only from springs to towns
    edges = []
    for spring in springs:
        for town in towns:
            d = distance(hills[spring - 1], hills[town - 1])
            if d <= q:
                heappush(edges, (d, spring - 1, town - 1))

    # Kruskal's algorithm to find minimum spanning tree
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1
            return True
        return False

    total_length = 0
    edges_used = 0

    while edges and edges_used < t:
        d, u, v = heappop(edges)
        if union(u, v):
            total_length += d
            edges_used += 1

    if edges_used == t:
        print(f"{total_length:.6f}")
    else:
        print("IMPOSSIBLE")

