import sys
import math
from heapq import heappop, heappush

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def distance(hill1, hill2):
    x1, y1, h1 = hill1
    x2, y2, h2 = hill2
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2 + (h1 - h2) ** 2)

def min_total_length(n, s, t, q, hills, springs, towns):
    graph = {i: [] for i in range(1, n + 1)}
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            dist = distance(hills[i - 1], hills[j - 1])
            if dist <= q and hills[i - 1][2] > hills[j - 1][2]:
                graph[i].append((dist, j))
            if dist <= q and hills[j - 1][2] > hills[i - 1][2]:
                graph[j].append((dist, i))

    def dijkstra(source, target):
        pq = [(0, source)]
        dist = {i: float('inf') for i in range(1, n + 1)}
        dist[source] = 0
        while pq:
            current_dist, current_node = heappop(pq)
            if current_node == target:
                return current_dist
            if current_dist > dist[current_node]:
                continue
            for edge_dist, neighbor in graph[current_node]:
                new_dist = current_dist + edge_dist
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heappush(pq, (new_dist, neighbor))
        return float('inf')

    total_length = 0
    for town in towns:
        min_length = float('inf')
        for spring in springs:
            length = dijkstra(spring, town)
            if length < min_length:
                min_length = length
        if min_length == float('inf'):
            return "IMPOSSIBLE"
        total_length += min_length

    return total_length

def main():
    n, s, t, q = read_ints()
    hills = [read_ints() for _ in range(n)]
    springs = read_ints()
    towns = read_ints()
    result = min_total_length(n, s, t, q, hills, springs, towns)
    if result == "IMPOSSIBLE":
        print(result)
    else:
        print(f"{result:.6f}")

