def calculate_areas():
    import sys
    input = sys.stdin.read
    from collections import deque

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        points = sorted(points)
        if len(points) <= 1:
            return points

        lower = []
        for p in points:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(points):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        return lower[:-1] + upper[:-1]

    def polygon_area(points):
        area = 0
        n = len(points)
        for i in range(n):
            j = (i + 1) % n
            area += points[i][0] * points[j][1]
            area -= points[j][0] * points[i][1]
        return abs(area) / 2.0

    data = input().split()
    N = int(data[0])
    points = [(int(data[i * 2 + 1]), int(data[i * 2 + 2])) for i in range(N)]
    operations = data[N * 2 + 1]

    points_dict = {p: i for i, p in enumerate(points)}
    points_set = set(points)
    results = []

    for op in operations:
        hull = convex_hull(list(points_set))
        area = polygon_area(hull)
        results.append(f"{area:.1f}")

        if op == 'L':
            min_x = min(points_set, key=lambda p: p[0])
            points_set.remove(min_x)
        elif op == 'R':
            max_x = max(points_set, key=lambda p: p[0])
            points_set.remove(max_x)
        elif op == 'U':
            max_y = max(points_set, key=lambda p: p[1])
            points_set.remove(max_y)
        elif op == 'D':
            min_y = min(points_set, key=lambda p: p[1])
            points_set.remove(min_y)

    print("\n".join(results))

