    data = input().splitlines()

    n, c = map(int, data[0].split())
    encounters = []

    for i in range(1, c + 1):
        a, b, y = map(int, data[i].split())
        encounters.append((a, b, y))

    encounters.sort(key=lambda x: x[2])

    def can_divide(year):
        from collections import defaultdict, deque

        graph = defaultdict(list)
        for a, b, y in encounters:
            if y < year:
                graph[a].append(b)
                graph[b].append(a)

        visited = [False] * (n + 1)
        component_sizes = []

        def bfs(start):
            queue = deque([start])
            visited[start] = True
            size = 0
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            return size

        for i in range(1, n + 1):
            if not visited[i]:
                component_size = bfs(i)
                component_sizes.append(component_size)

        component_sizes.sort(reverse=True)
        if len(component_sizes) == 1:
            return component_sizes[0] <= 2 * n // 3
        elif len(component_sizes) > 1:
            return component_sizes[0] <= 2 * n // 3 and component_sizes[0] + component_sizes[1] <= n

        return False

    left, right = 1948, 2008
    result = "Impossible"

    while left < right:
        mid = (left + right) // 2
        if can_divide(mid):
            result = mid
            right = mid
        else:
            left = mid + 1

    if result == "Impossible" and can_divide(left):
        result = left

