def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    MOD = 10**9 + 7
    n = int(data[0])
    color_matrix = []
    index = 1
    for i in range(n):
        color_matrix.append(list(map(int, data[index:index + n])))
        index += n

    # Precompute the maximum clique size for each color
    from collections import defaultdict
    color_cliques = defaultdict(list)

    for i in range(n):
        for j in range(i + 1, n):
            color = color_matrix[i][j]
            color_cliques[color].append((i, j))

    max_clique_size = [0] * 301

    for color in range(1, 301):
        if color in color_cliques:
            edges = color_cliques[color]
            adj = [0] * n
            for u, v in edges:
                adj[u] |= (1 << v)
                adj[v] |= (1 << u)

            # Find the maximum clique size using bitmask dp
            dp = [0] * (1 << n)
            for mask in range(1, 1 << n):
                last = (mask & -mask).bit_length() - 1
                prev_mask = mask ^ (1 << last)
                if prev_mask == 0 or (adj[last] & prev_mask) == prev_mask:
                    dp[mask] = dp[prev_mask] + 1
                max_clique_size[color] = max(max_clique_size[color], dp[mask])

    # Calculate the sum of f(S) over all non-empty subsets S
    total_sum = 0
    for mask in range(1, 1 << n):
        max_f = 0
        for color in range(1, 301):
            if max_clique_size[color] > 0:
                subset_mask = 0
                for i in range(n):
                    if mask & (1 << i):
                        subset_mask |= (1 << i)
                if subset_mask:
                    max_f = max(max_f, max_clique_size[color])
        total_sum = (total_sum + max_f) % MOD

    print(total_sum)

