        index += 4

    intersection_points = set()

    for i in range(n):
        for j in range(i + 1, n):
            p1, q1 = lines[i]
            p2, q2 = lines[j]
            if do_intersect(p1, q1, p2, q2):
                point = intersection_point(p1, q1, p2, q2)
