def maximize_probability():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    probabilities = list(map(float, data[1:]))

    max_probability = 0.0

    for mask in range(1, 1 << n):
        prob_exactly_one = 0.0
        prob_none = 1.0
        prob_more_than_one = 0.0

        for i in range(n):
            if mask & (1 << i):
                prob_none *= (1 - probabilities[i])

        for i in range(n):
            if mask & (1 << i):
                prob_exactly_one += probabilities[i] * prob_none / (1 - probabilities[i])

        prob_more_than_one = 1 - prob_none - prob_exactly_one

        if prob_more_than_one < 1e-9:
            max_probability = max(max_probability, prob_exactly_one)

    print(f"{max_probability:.12f}")

